const cards = [...ring.querySelectorAll(".vc")];
const reduceM = matchMedia("(prefers-reduced-motion: reduce)").matches;
let ang = 0, orbOn = false, lastT = 0;
function orbit(t){
const dt = lastT ? Math.min(50, t - lastT) : 16; lastT = t;
if (!reduceM) ang += dt * 0.00016;
const m = innerWidth < 768, cw = m ? 84 : 200, RX = Math.max(60, Math.min(m ? 150 : 360, document.querySelector('.palco').clientWidth / 2 - cw / 2 - 8)), RY = m ? 30 : 70;
cards.forEach((c, i) => {
const a = ang + i * Math.PI * 2 / N, s = Math.sin(a), k = (1 + s) / 2;
c.style.transform = `translate3d(${(Math.cos(a) * RX).toFixed(1)}px,${(s * RY - Math.cos(a) * RX * .14).toFixed(1)}px,0) scale(${(.62 + .38 * k).toFixed(3)})`;
c.style.opacity = (.35 + .65 * k).toFixed(2);
c.style.zIndex = k > .5 ? 60 + Math.round(k * 30) : 10 + Math.round(k * 30);
c.style.filter = `blur(${((1 - k) * 1.6).toFixed(2)}px)`;
});
if (orbOn) requestAnimationFrame(orbit);
}
orbit(0);
new IntersectionObserver(es => es.forEach(e => {
if (e.isIntersecting && !orbOn) { orbOn = true; lastT = 0; requestAnimationFrame(orbit); } else if (!e.isIntersecting) orbOn = false;
}), { rootMargin: "200px 0px" }).observe(document.querySelector(".palco"));
